-- source_reference: Petrobras planilha de codigos de atrasos dos voos, fornecida pelo usuario em 2026-09-20.
-- operational_decision: seed canonical AA41-AA94 delay justification catalog for empresa_id 6, preserving source categories and descriptions; searchable by code, name, category and description.
-- dry_run_required: validate additive category column, 54 canonical rows, tenant isolation and zero mutation outside empresa_id 6.
-- rollback_plan_required: additive category column remains; seeded rows can be inactivated/compensated by exact code if application rollback is required.

ALTER TABLE cv_justificativas_voo ADD COLUMN categoria TEXT;

CREATE INDEX IF NOT EXISTS idx_cv_justificativas_voo_empresa_categoria
  ON cv_justificativas_voo (empresa_id, categoria, ordem)
  WHERE deleted_at IS NULL;

